function a(t){if(t==null||!Number.isFinite(t)||t<0)return"-";if(t<1e3)return`${t}ms`;const n=Math.floor(t/1e3),e=Math.floor(n/86400),o=Math.floor(n%86400/3600),u=Math.floor(n%3600/60),i=n%60,r=[];return e>0&&r.push(`${e}d`),o>0&&r.push(`${o}h`),u>0&&r.push(`${u}m`),r.push(`${i}s`),r.join(" ")}function f(t){if(t==null||!Number.isFinite(t))return"-";const n=new Date(t),e=o=>String(o).padStart(2,"0");return`${n.getFullYear()}-${e(n.getMonth()+1)}-${e(n.getDate())} ${e(n.getHours())}:${e(n.getMinutes())}:${e(n.getSeconds())}`}function s(t){if(t==null||!Number.isFinite(t)||t<0)return"-";if(t<1024)return`${t} B`;const n=["KB","MB","GB","TB"];let e=t,o="B";for(const u of n){if(e<1024)break;e/=1024,o=u}return`${e.toFixed(1)} ${o}`}function c(t){return t==="queued"||t==="running"||t==="unknown"}export{s as a,a as b,f,c as i};
